import i18n from 'i18next'
import {initReactI18next, useTranslation} from 'react-i18next'
import React from 'react'

const resources = {
    ru: {translation: {profile: 'Профиль', users: 'Пользователи', chat: 'Чат', news: 'Новости', todo: 'Список дел', settings: 'Настройки', logout: 'Выйти', notifications: 'Уведомления', noNotifications: 'Нет уведомлений', language: 'Язык'}},
    en: {translation: {profile: 'Profile', users: 'Users', chat: 'Chat', news: 'News', todo: 'To Do List', settings: 'Settings', logout: 'Log out', notifications: 'Notifications', noNotifications: 'No notifications', language: 'Language'}}
}
i18n.use(initReactI18next).init({resources, lng: localStorage.getItem('language') || 'ru', fallbackLng: 'ru', interpolation: {escapeValue: false}})
export function I18nProvider({children}: {children: React.ReactNode}) { return <>{children}</> }
export const useI18n = () => { const {t, i18n: instance} = useTranslation(); return {t, language: instance.language, setLanguage: (language: 'ru' | 'en') => {localStorage.setItem('language', language); void instance.changeLanguage(language)}} }
