import React, {useContext, useEffect, useState} from 'react'
import {Box, Button, CardMedia, Chip, FormControl, Grid, IconButton, InputLabel, MenuItem, Paper, Select, TextField, Tooltip, Typography} from '@mui/material'
import DeleteForeverIcon from '@mui/icons-material/DeleteForever'
import HelpOutlineIcon from '@mui/icons-material/HelpOutline'
import EditOutlinedIcon from '@mui/icons-material/EditOutlined'
import imgF from '../../../assets/image/logoNoImg.png'
import {serverTimestamp, doc, setDoc} from 'firebase/firestore'
import {NewsAddMessagesType, quickBytesType, UserRole} from '../../../types/types'
import {newsAPI} from '../../../api/news-api'
import {NavLink} from 'react-router-dom'
import {FriendsAvatarGroup} from './FriendsAvatarGroup/FriendsAvatarGroup'
import {profileAPI} from '../../../api/profile-api'
import {quickBytesAPI} from '../../../api/quickBytes-api'
import {Context, FirebaseUserAndUserType} from '../../../App'
import {roleLabels} from '../../../roles'

export function ProfileData({profile, author = false}: any) {
    const {user, setUser, firestore} = useContext(Context)
    const [value, setValue] = useState(''); const [valueSpeaks, setValueSpeaks] = useState('Говорит')
    const [qBPostsUser, setqBPostsUser] = useState<quickBytesType[]>([]); const [newsPosts, setNewsPosts] = useState<NewsAddMessagesType[]>([]); const [newsLoading, setNewsLoading] = useState(true); const [roleEditing, setRoleEditing] = useState(false)
    const [displayedRole, setDisplayedRole] = useState<UserRole>((profile?.role || 'user') as UserRole)
    const inputRef = React.useRef<HTMLInputElement>()
    const canManageRole = user?.role === 'admin' && Boolean(profile?.uid)
    useEffect(() => { setDisplayedRole((profile?.role || 'user') as UserRole) }, [profile?.role])
    const saveRole = async (nextRole: UserRole) => { if (!canManageRole) return; await setDoc(doc(firestore, 'users', profile.uid), {role: nextRole}, {merge: true}); setDisplayedRole(nextRole); if (user?.uid === profile.uid) setUser({...user, role: nextRole}); setRoleEditing(false) }
    const clearQB = () => {setValue(''); inputRef.current?.focus()}
    const deleteQB = async (id: string) => {if (!user) return; const data = await profileAPI.delQBPost(id, user.uid); setUser({...user, qBPostsId: data.qBPostsId || []} as FirebaseUserAndUserType); await quickBytesAPI.delQuickBytes(id)}
    const sendQB = async () => {if (!user || !value.trim()) {clearQB(); return}; const id = await quickBytesAPI.addQuickBytes({text: value.trim(), userId: user.uid, speak: valueSpeaks, createdAt: serverTimestamp()}); const data = await profileAPI.addQBPost(id, user.uid); setUser({...user, qBPostsId: data.qBPostsId || []} as FirebaseUserAndUserType); clearQB()}
    useEffect(() => {if (!profile?.uid) return; setNewsLoading(true); newsAPI.getNewsByAuthor(profile.uid, user?.uid || '').then(setNewsPosts).catch(() => setNewsPosts([])).finally(() => setNewsLoading(false))}, [profile?.uid, user?.uid])
    useEffect(() => {if (!profile?.qBPostsId?.length) {setqBPostsUser([]); return}; quickBytesAPI.getQuickBytesByIds(profile.qBPostsId).then(posts => setqBPostsUser(posts.slice(-7))).catch(() => setqBPostsUser([]))}, [profile?.qBPostsId])
    return <Grid container spacing={2} alignItems="stretch">
        <Grid item xs={12} md={4}><Paper className="app-panel" sx={{height: '100%', overflow: 'hidden'}}><CardMedia component="img" src={profile?.photoURL || imgF} alt={profile?.displayName || 'Аватар пользователя'} sx={{height: {xs: 220, md: 280}, objectFit: 'cover'}}/><Box sx={{p: 2}}><Typography variant="h5" gutterBottom>{profile?.displayName}</Typography><StackRole role={displayedRole} editing={roleEditing} canManage={canManageRole} onEdit={() => setRoleEditing(true)} onChange={saveRole}/><Typography color="text.secondary">Друзей: {profile?.friends?.length || 0}</Typography><FriendsAvatarGroup author={author} friends={profile?.friends || []}/><Typography variant="caption" display="block" sx={{mt: 2}}>ID: {profile?.uid}</Typography></Box></Paper></Grid>
        <Grid item xs={12} md={8}><Paper className="app-panel" sx={{p: 2, height: '100%'}}><Typography variant="h5" gutterBottom>О пользователе</Typography><Grid container spacing={2}>{[['Email', profile?.email], ['Возраст', profile?.age], ['Пол', profile?.sex], ['Страна', profile?.country], ['Обо мне', profile?.aboutYou]].map(([label, value]) => <Grid item xs={12} sm={6} key={label as string}><Typography variant="caption" color="text.secondary">{label}</Typography><Typography sx={{overflowWrap: 'anywhere'}}>{value || 'Не указано'}</Typography></Grid>)}</Grid></Paper></Grid>
        <Grid item xs={12} md={8}><Paper className="app-panel" sx={{p: 2, height: '100%'}}><Typography variant="h5" gutterBottom>Опубликованные новости</Typography>{newsLoading ? <Typography color="text.secondary">Загрузка…</Typography> : newsPosts.length ? <Grid container spacing={2}>{newsPosts.map(post => <Grid item xs={12} sm={6} key={post.id}><Box component={NavLink} to={'/news/' + post.id} sx={{display: 'block', color: 'inherit', textDecoration: 'none', border: 1, borderColor: 'divider', borderRadius: 2, overflow: 'hidden'}}><CardMedia component="img" src={post.img || imgF} alt={post.title} sx={{height: 140, objectFit: 'cover'}}/><Typography sx={{p: 1.5, fontWeight: 700}}>{post.title}</Typography><Typography variant="caption" color="text.secondary" sx={{display: 'block', px: 1.5, pb: 1}}>Создано: {post.createdAt ? new Intl.DateTimeFormat('ru-RU', {dateStyle: 'medium', timeStyle: 'short'}).format(new Date(post.createdAt.seconds * 1000)) : '—'}<br/>Первая публикация: {post.createdAt ? new Intl.DateTimeFormat('ru-RU', {dateStyle: 'medium', timeStyle: 'short'}).format(new Date(post.createdAt.seconds * 1000)) : '—'}</Typography></Box></Grid>)}</Grid> : <Typography color="text.secondary">Пользователь ещё не опубликовал новости.</Typography>}</Paper></Grid>
        <Grid item xs={12} md={4}><Paper className="app-panel" sx={{p: 2, height: '100%'}}><Box sx={{display: 'flex', alignItems: 'center', gap: 1}}><Typography variant="h6">QuickBytes</Typography><Tooltip title="Короткие сообщения пользователя"><HelpOutlineIcon fontSize="small"/></Tooltip></Box>{qBPostsUser.length ? qBPostsUser.map(post => <Box key={post.id} sx={{p: 1.25, my: 1, borderRadius: 2, bgcolor: 'action.hover', border: 1, borderColor: 'divider'}}><Box sx={{display: 'flex', justifyContent: 'space-between', gap: 1}}><Typography sx={{overflowWrap: 'anywhere'}}>{post.text}</Typography>{author && <IconButton size="small" sx={{width: 28, height: 28, flexShrink: 0}} aria-label="Удалить QuickByte" onClick={() => void deleteQB(post.id)}><DeleteForeverIcon fontSize="small"/></IconButton>}</Box><Typography variant="caption" color="text.secondary" display="block" sx={{mt: .5}}>{post.createdAt ? new Intl.DateTimeFormat('ru-RU', {dateStyle: 'medium', timeStyle: 'short'}).format(new Date(post.createdAt.seconds * 1000)) : 'Дата неизвестна'}</Typography></Box>) : <Typography color="text.secondary" sx={{py: 2}}>{author ? 'Вы ещё ничего не написали в QuickBytes.' : 'У этого пользователя пока нет QuickBytes.'}</Typography>}{author && <Box sx={{mt: 2}}><TextField fullWidth multiline maxRows={3} value={value} inputRef={inputRef} label="Новое QuickByte" onChange={e => setValue(e.target.value)} inputProps={{maxLength: 200}}/><Box sx={{mt: 1.5}}><StackRoleInput value={valueSpeaks} onChange={setValueSpeaks}/></Box><Button sx={{mt: 1.5}} variant="contained" onClick={() => void sendQB()} disabled={!value.trim()}>Опубликовать</Button></Box>}</Paper></Grid>
    </Grid>
}
function StackRole({role, editing, canManage, onEdit, onChange}: {role: UserRole; editing: boolean; canManage: boolean; onEdit: () => void; onChange: (role: UserRole) => void}) {return <Box sx={{display: 'flex', alignItems: 'center', gap: 1, mb: 1}}><Typography variant="body2" color="text.secondary">Роль</Typography>{editing && canManage ? <Select size="small" value={role || 'user'} onChange={e => onChange(e.target.value as UserRole)}>{Object.entries(roleLabels).map(([value, label]) => <MenuItem value={value} key={value}>{label}</MenuItem>)}</Select> : <Chip size="small" label={roleLabels[role] || roleLabels.user}/>} {canManage && !editing && <IconButton size="small" aria-label="Изменить роль пользователя" onClick={onEdit}><EditOutlinedIcon fontSize="small"/></IconButton>}</Box>}
function StackRoleInput({value, onChange}: {value: string; onChange: (value: string) => void}) {return <FormControl fullWidth size="small" sx={{mt: 1}}><InputLabel id="quickbyte-speak-label">Тип сообщения</InputLabel><Select labelId="quickbyte-speak-label" value={value} label="Тип сообщения" onChange={e => onChange(e.target.value)}><MenuItem value="Говорит">Говорит</MenuItem><MenuItem value="Кричит">Кричит</MenuItem></Select></FormControl>}
