import {collection, getDocs, getFirestore} from 'firebase/firestore'

export async function getNewsStats(newsId: string) {
    const db = getFirestore()
    const [newsReactions, comments] = await Promise.all([
        getDocs(collection(db, 'news', newsId, 'reactions')),
        getDocs(collection(db, 'news', newsId, 'comments'))
    ])
    let likeCount = 0
    let dislikeCount = 0
    newsReactions.forEach(reaction => {
        const type = reaction.data().type
        if (type === 'like') likeCount += 1
        if (type === 'dislike') dislikeCount += 1
    })
    return {commentCount: comments.size, likeCount, dislikeCount}
}
