import React, {useEffect, useState} from 'react'
import {Alert, CardMedia, Dialog, Tooltip, DialogActions, DialogContent, DialogContentText, DialogTitle, Grid, IconButton, Paper, Stack, Typography, Button} from '@mui/material'
import VisibilityIcon from '@mui/icons-material/Visibility'
import VisibilityOffIcon from '@mui/icons-material/VisibilityOff'
import DeleteOutlineIcon from '@mui/icons-material/DeleteOutline'
import EditIcon from '@mui/icons-material/Edit'
import {NavLink} from 'react-router-dom'
import logoNoImg from '../../assets/image/logoNoImg.png'
import {newsAPI} from '../../api/news-api'
import {NewsAddMessagesType} from '../../types/types'

export function UserNewsManager({userId}: {userId: string}) {
    const [news, setNews] = useState<NewsAddMessagesType[]>([])
    const [selected, setSelected] = useState<NewsAddMessagesType | null>(null)
    const [visibilityTarget, setVisibilityTarget] = useState<NewsAddMessagesType | null>(null)
    const [error, setError] = useState('')
    const load = async () => { setError(''); try { setNews(await newsAPI.getNewsByAuthor(userId, userId)) } catch (error) { console.error('Не удалось загрузить новости пользователя', error); setError('Не удалось загрузить ваши новости') } }
    useEffect(() => { load() }, [userId])
    const toggle = async () => { if (!visibilityTarget) return; try { await newsAPI.setVisibility(visibilityTarget.id, userId, visibilityTarget.isPublic === false); setVisibilityTarget(null); await load() } catch { setError('Не удалось изменить видимость новости') } }
    const remove = async () => { if (!selected) return; try { await newsAPI.deleteNews(selected.id, userId); setSelected(null); await load() } catch { setError('Не удалось удалить новость') } }
    return <Paper className="app-panel" sx={{p: 2}}><Typography variant="h5" gutterBottom>Мои новости</Typography>{error && <Alert severity="error" sx={{mb: 2}}>{error}</Alert>}{news.length === 0 ? <Typography color="text.secondary">У вас пока нет опубликованных новостей.</Typography> : <Grid container spacing={2}>{news.map(item => <Grid item xs={12} sm={6} md={4} key={item.id}><Paper variant="outlined" sx={{overflow: 'hidden', height: '100%'}}><CardMedia component="img" image={item.img || logoNoImg} alt={item.title} sx={{height: 140, objectFit: 'cover'}}/><Typography sx={{p: 1.5, fontWeight: 600, minHeight: 64}}>{item.title}</Typography><Typography variant="caption" color="text.secondary" sx={{display: 'block', px: 1.5, pb: 1}}>Создано: {item.createdAt ? new Intl.DateTimeFormat('ru-RU', {dateStyle: 'medium', timeStyle: 'short'}).format(new Date(item.createdAt.seconds * 1000)) : '—'}<br/>Первая публикация: {item.createdAt ? new Intl.DateTimeFormat('ru-RU', {dateStyle: 'medium', timeStyle: 'short'}).format(new Date(item.createdAt.seconds * 1000)) : '—'}</Typography><Stack direction="row" justifyContent="flex-end" sx={{px: 1, pb: 1}}><Tooltip title="Открыть просмотр"><IconButton size="small" component={NavLink} to={`/news/${item.id}`} aria-label="Открыть новость"><VisibilityIcon fontSize="small"/></IconButton></Tooltip><Tooltip title={item.isPublic === false ? 'Опубликовать' : 'Сделать приватной'}><IconButton size="small" aria-label={item.isPublic === false ? 'Сделать публичной' : 'Сделать приватной'} onClick={() => setVisibilityTarget(item)} color={item.isPublic === false ? 'default' : 'primary'}>{item.isPublic === false ? <VisibilityOffIcon fontSize="small"/> : <VisibilityIcon fontSize="small"/>}</IconButton></Tooltip><Tooltip title="Редактировать"><IconButton size="small" component={NavLink} to={`/news/${item.id}?edit=1`} aria-label="Редактировать новость"><EditIcon fontSize="small"/></IconButton></Tooltip><Tooltip title="Удалить"><IconButton size="small" aria-label="Удалить новость" color="error" onClick={() => setSelected(item)}><DeleteOutlineIcon fontSize="small"/></IconButton></Tooltip></Stack></Paper></Grid>)}</Grid>}<Dialog open={Boolean(visibilityTarget)} onClose={() => setVisibilityTarget(null)}><DialogTitle>{visibilityTarget?.isPublic === false ? 'Опубликовать запись?' : 'Скрыть запись?'}</DialogTitle><DialogContent><DialogContentText>{visibilityTarget?.isPublic === false ? 'Вы действительно хотите опубликовать запись? Она будет доступна всем пользователям на странице новостей.' : 'Запись пропадёт из общего доступа и останется доступна только вам.'}</DialogContentText></DialogContent><DialogActions><Button onClick={() => setVisibilityTarget(null)}>Нет</Button><Button onClick={toggle}>Да</Button></DialogActions></Dialog><Dialog open={Boolean(selected)} onClose={() => setSelected(null)}><DialogTitle>Подтвердите удаление</DialogTitle><DialogContent><DialogContentText>Точно удалить «{selected?.title}»?</DialogContentText></DialogContent><DialogActions><Button onClick={() => setSelected(null)}>Нет</Button><Button color="error" onClick={remove}>Да, удалить</Button></DialogActions></Dialog></Paper>
}
