import {deleteDoc, doc, getDocs, getFirestore, setDoc, collection, serverTimestamp} from 'firebase/firestore'
export async function getNewsReaction(newsId: string, userId?: string) { if (!userId) return undefined; const snap = await getDocs(collection(getFirestore(), 'news', newsId, 'reactions')); return snap.docs.find(d => d.id === userId)?.data().type as 'like' | 'dislike' | undefined }
export async function toggleNewsReaction(newsId: string, userId: string, reaction: 'like' | 'dislike') { const ref = doc(getFirestore(), 'news', newsId, 'reactions', userId); const existing = await getNewsReaction(newsId, userId); if (existing === reaction) await deleteDoc(ref); else await setDoc(ref, {type: reaction, createdAt: serverTimestamp(), updatedAt: null}, {merge: true}) }
